1: /**
2:  * F11.2j explorer-subagent runner — the bounded `::explore` session (§5.U sibling of the plan-critique runner).
3:  *
4:  * One worker `explore` call = one bounded, read-only session with a FRESH context window. A resident-only selector may
5:  * route it to a smaller empirically tool-capable model; otherwise it uses the worker unchanged. Owns the per-session
6:  * query budget; every degraded path resolves to null so exploration never
7:  * blocks the worker (the tool tells it to fall back to its own retrieval).
8:  */
9: 
10: import { isHomeAgentSessionId } from "../core/home-agent-session";
11: import { isDerivedTaskSessionId } from "../core/synthetic-task-id";
12: import { recordSelfObservation } from "../telemetry/self-observation-sink";
13: import { type AgentSandboxManager, createAgentSandboxToolExecutors } from "./nklein-agent-sandbox";
14: import { createAgentSandboxExtraTools } from "./nklein-agent-sandbox-extra-tools";
15: import {
16: 	buildExplorerSeedPrompt,
17: 	type NKleinExplorerQueryHandler,
18: 	type NKleinExplorerResult,
19: } from "./nklein-explorer-tool";
20: import type { NKleinTaskRestartLaunchConfig } from "./nklein-launch-config";
21: import type { NKleinPauseController } from "./nklein-pause-controller";
22: import type {
23: 	RuntimeTaskSessionStartResult,
24: 	StartRuntimeTaskSessionFromLaunchConfigInput,
25: } from "./nklein-runtime-session-input";
26: import type { SecondarySessionHarness } from "./nklein-secondary-session-harness";
27: import { createSessionId } from "./nklein-session-state";
28: 
29: const EXPLORER_NUDGE_PROMPT =
30: 	"Submit your findings now by calling the submit_citations tool with your answer and citations. Do not reply in prose.";
31: 
32: /**
33:  * Classify an explore-query failure as a timeout vs a generic error. Pure, so the distinction the observation
34:  * carries is testable without spinning a real explorer session. A timeout is worth telling apart because "explore
35:  * keeps timing out" is an actionable pattern (budget/model too slow), where a one-off error is noise.
36:  */
37: export function classifyExploreFailure(message: string): "timeout" | "error" {
38: 	return /timeout|timed out|aborted/i.test(message) ? "timeout" : "error";
39: }
40: 
41: export interface ExplorerRunnerDeps {
42: 	getAgentSandboxManager(): AgentSandboxManager | null;
43: 	getLaunchConfig(taskId: string): NKleinTaskRestartLaunchConfig | null;
44: 	resolveExplorerLaunchConfig(workerLaunch: NKleinTaskRestartLaunchConfig): Promise<NKleinTaskRestartLaunchConfig>;
45: 	getPauseController(): NKleinPauseController;
46: 	getHarness(): SecondarySessionHarness;
47: 	getBaseRef(taskId: string): string | null;
48: 	startRuntimeSession(input: StartRuntimeTaskSessionFromLaunchConfigInput): Promise<RuntimeTaskSessionStartResult>;
49: 	sendTaskSessionInput(taskId: string, prompt: string, admissionParentTaskId: string): Promise<unknown>;
50: 	defaultTimeoutMs: number;
51: 	maxNudges: number;
52: 	/** Per-run explore-query budget (each query is one bounded read-only session on the task's endpoint). */
53: 	runBudget: number;
54: }
55: 
56: export interface ExplorerRunner {
57: 	/**
58: 	 * Build the worker-side `explore` executor for a session — or undefined for synthetic/home sessions (an
59: 	 * `::explore` session must never recurse into another explorer). Enforces the per-run budget; every failure
60: 	 * degrades to null (the tool renders an honest fallback message).
61: 	 */
62: 	buildExploreHandler(taskId: string, projectRepoPath: string): NKleinExplorerQueryHandler | undefined;
63: }
64: 
65: export function createExplorerRunner(deps: ExplorerRunnerDeps): ExplorerRunner {
66: 	async function runExplorerSession(input: {
67: 		taskId: string;
68: 		projectRepoPath: string;
69: 		baseRef: string;
70: 		question: string;
71: 	}): Promise<NKleinExplorerResult | null> {
72: 		const sandboxManager = deps.getAgentSandboxManager();
73: 		if (!sandboxManager) {
74: 			return null;
75: 		}
76: 		const workerLaunch = deps.getLaunchConfig(input.taskId) ?? null;
77: 		if (!workerLaunch?.providerId || !workerLaunch.modelId) {
78: 			return null;
79: 		}
80: 		const selectedLaunch = await deps.resolveExplorerLaunchConfig(workerLaunch).catch(() => workerLaunch);
81: 		const launchConfig: NKleinTaskRestartLaunchConfig = {
82: 			...selectedLaunch,
83: 			workspaceRoot: input.projectRepoPath,
84: 		};
85: 		if (launchConfig.modelId !== workerLaunch.modelId) {
86: 			recordSelfObservation({
87: 				signal: "custom",
88: 				severity: "info",
89: 				message: `Explorer for ${input.taskId} routed from ${workerLaunch.modelId} to smaller loaded model ${launchConfig.modelId}.`,
90: 				taskId: input.taskId,
91: 				metadata: {
92: 					category: "explorer_smaller_model_routed",
93: 					workerModel: workerLaunch.modelId,
94: 					explorerModel: launchConfig.modelId,
95: 				},
96: 			});
97: 		}
98: 		const explorerTaskId = `${input.taskId}::explore`;
99: 		return deps.getHarness().runBracketed(
100: 			{
101: 				syntheticTaskId: explorerTaskId,
102: 				projectRepoPath: input.projectRepoPath,
103: 				baseRef: input.baseRef,
104: 				defaultTimeoutMs: deps.defaultTimeoutMs,
105: 				errorLabel: "Explorer session",
106: 			},
107: 			async ({ workspace, deadlineMs, runBoundedTurn }) => {
108: 				let findings: NKleinExplorerResult | null = null;
109: 				await runBoundedTurn(
110: 					deps.startRuntimeSession({
111: 						taskId: explorerTaskId,
112: 						admissionParentTaskId: input.taskId,
113: 						cwd: workspace.workdir,
114: 						workspaceRoot: input.projectRepoPath,
115: 						prompt: buildExplorerSeedPrompt(input.question),
116: 						launchConfig,
117: 						contextScope: "minimal",
118: 						onExplorerCitationsSubmitted: (result) => {
119: 							findings = result;
120: 						},

120: 						},
121: 						toolExecutors: createAgentSandboxToolExecutors(sandboxManager, explorerTaskId, {
122: 							pauseController: deps.getPauseController(),
123: 						}),
124: 						extraTools: createAgentSandboxExtraTools(sandboxManager, explorerTaskId, {
125: 							sessionId: createSessionId(explorerTaskId),
126: 							contextWindow: launchConfig.contextWindow ?? undefined,
127: 							maxFileLines: launchConfig.maxAgentWritableFileLines ?? null,
128: 						}),
129: 					}),
130: 				);
131: 				for (let nudge = 0; findings === null && nudge < deps.maxNudges && Date.now() < deadlineMs; nudge += 1) {
132: 					await runBoundedTurn(deps.sendTaskSessionInput(explorerTaskId, EXPLORER_NUDGE_PROMPT, input.taskId));
133: 				}
134: 				return findings;
135: 			},
136: 		);
137: 	}
138: 
139: 	function buildExploreHandler(taskId: string, projectRepoPath: string): NKleinExplorerQueryHandler | undefined {
140: 		if (isDerivedTaskSessionId(taskId) || isHomeAgentSessionId(taskId)) {
141: 			return undefined;
142: 		}
143: 		// One closure belongs to one worker session. Keeping this counter on the runner made six historical calls disable
144: 		// exploration globally for every later task in the service lifetime.
145: 		let exploreQueriesUsed = 0;
146: 		return async (question) => {
147: 			if (exploreQueriesUsed >= deps.runBudget) {
148: 				return null;
149: 			}
150: 			if (!deps.getAgentSandboxManager()) {
151: 				return null;
152: 			}
153: 			exploreQueriesUsed += 1;
154: 			return await runExplorerSession({
155: 				taskId,
156: 				projectRepoPath,
157: 				baseRef: deps.getBaseRef(taskId) ?? "HEAD",
158: 				question,
159: 			}).catch((error: unknown) => {
160: 				// P21.7 follow-up: the return stays null (the tool renders an honest fallback — nothing to salvage
161: 				// from a read-only helper query), but the FAILURE was previously swallowed silently, so a timed-out
162: 				// explore looked identical to one that legitimately found nothing. Record the classified reason so
163: 				// "explore keeps timing out" is visible instead of invisible — the record-the-decline rule applied
164: 				// to a helper path.
165: 				const message = error instanceof Error ? error.message : String(error);
166: 				const reason = classifyExploreFailure(message);
167: 				try {
168: 					recordSelfObservation({
169: 						signal: "custom",
170: 						severity: "info",
171: 						message: `Explore query for ${taskId} failed: ${reason === "timeout" ? "timed out" : "errored"}.`,
172: 						taskId,
173: 						metadata: { category: "explore_query_failed", reason },
174: 					});
175: 				} catch {
176: 					// Telemetry must never break the explore fallback.
177: 				}
178: 				return null;
179: 			});
180: 		};
181: 	}
182: 
183: 	return { buildExploreHandler };
184: }
