100: 				const caps = (model.capabilities ?? undefined) as RawV1Capabilities | undefined;
101: 				const toolUse = typeof caps?.trained_for_tool_use === "boolean" ? caps.trained_for_tool_use : undefined;
102: 				const vision = typeof caps?.vision === "boolean" ? caps.vision : undefined;
103: 				const reasoning = caps && caps.reasoning != null ? true : undefined;
104: 				const architecture = asString(model.architecture);
105: 				const maxContextLength =
106: 					typeof model.max_context_length === "number" && Number.isFinite(model.max_context_length)
107: 						? model.max_context_length
108: 						: undefined;
109: 				descriptors.push({
110: 					runtimeId,
111: 					modelKey: asString(model.key) ?? runtimeId,
112: 					isEmbedding: model.type === "embedding",
113: 					...(toolUse !== undefined ? { toolUse } : {}),
114: 					...(vision !== undefined ? { vision } : {}),
115: 					...(reasoning !== undefined ? { reasoning } : {}),
116: 					...(architecture !== undefined ? { architecture } : {}),
117: 					...(maxContextLength !== undefined ? { maxContextLength } : {}),
