124: 		const isEmbedding = model.type === "embedding";
125: 		const caps = (model.capabilities ?? undefined) as RawV1Capabilities | undefined;
126: 		const toolUse = typeof caps?.trained_for_tool_use === "boolean" ? caps.trained_for_tool_use : undefined;
127: 		const vision = typeof caps?.vision === "boolean" ? caps.vision : undefined;
128: 		const reasoning = caps && caps.reasoning != null ? true : undefined;
129: 		const architecture = asString(model.architecture);
130: 		const maxContextLength =
131: 			typeof model.max_context_length === "number" && Number.isFinite(model.max_context_length)
132: 				? model.max_context_length
133: 				: undefined;
134: 		for (const rawInstance of instances) {
135: 			const instance = rawInstance as RawV1Instance;
136: 			const runtimeId = asString(instance?.id);
137: 			if (!runtimeId) {
138: 				continue;
139: 			}
140: 			const config =
141: 				instance.config && typeof instance.config === "object"
142: 					? (instance.config as { context_length?: unknown })
143: 					: null;
144: 			const loadedContextLength =
145: 				typeof config?.context_length === "number" && Number.isFinite(config.context_length)
146: 					? config.context_length
147: 					: undefined;
148: 			descriptors.push({
149: 				runtimeId,
150: 				modelKey: modelKey ?? runtimeId,
151: 				isEmbedding,
152: 				...(toolUse !== undefined ? { toolUse } : {}),
153: 				...(vision !== undefined ? { vision } : {}),
154: 				...(reasoning !== undefined ? { reasoning } : {}),
155: 				...(architecture !== undefined ? { architecture } : {}),
156: 				...(maxContextLength !== undefined ? { maxContextLength } : {}),
157: 				...(loadedContextLength !== undefined ? { loadedContextLength } : {}),
