33: /** Split an identifier or prose into lowercase tokens (camelCase / snake_case / punctuation aware). */
34: export function tokenizeForOverlap(text: string): Set<string> {
35: 	const tokens = new Set<string>();
36: 	for (const raw of text.split(/[^A-Za-z0-9]+/)) {
37: 		for (const piece of raw.replaceAll(/([a-z0-9])([A-Z])/g, "$1 $2").split(" ")) {
38: 			const token = piece.toLowerCase();
39: 			if (token.length >= 3) {
40: 				tokens.add(token);
41: 			}
42: 		}
43: 	}
44: 	return tokens;
45: }
