1: /**
2:  * F11.2k monorepo-aware task scoping — PURE core.
3:  *
4:  * In a multi-package repo a card's real working context is ONE package: its own scripts govern, its own
5:  * AGENTS.md/CLAUDE.md instructions apply, and edits outside it are usually scope creep. This core derives that
6:  * scope from the card's likely files + the repo's known package directories: the deepest package containing ALL
7:  * the files (root ⇒ no note — root is the default context), an honest spans-packages signal when they cross
8:  * boundaries (a real smell worth telling the worker, not an error), and the instruction files on the path from
9:  * the root to the package (root first, so the nearest file is read LAST and wins recency). The workspace scan
10:  * that supplies `packageDirs`/`instructionFiles` lives with the agent layer.
11:  */
12: 
13: export interface MonorepoTaskScopeInput {
14: 	/** The card's likely-touched files, workspace-relative. */
15: 	readonly taskFiles: readonly string[];
16: 	/** Directories containing a package.json, workspace-relative ("" = the repo root). */
17: 	readonly packageDirs: readonly string[];
18: 	/** All AGENTS.md / CLAUDE.md paths in the repo, workspace-relative. */
19: 	readonly instructionFiles: readonly string[];
20: }
21: 
22: export interface MonorepoTaskScope {
23: 	/** The single non-root package dir containing every task file; null when root-scoped or spanning. */
24: 	readonly packageDir: string | null;
25: 	/** The distinct packages the files resolve to when they CROSS boundaries; null otherwise. */
26: 	readonly spansPackages: readonly string[] | null;
27: 	/** Instruction files that govern the scope, outermost first (nearest last — recency wins). */
28: 	readonly instructionFilePaths: readonly string[];
29: 	/** Prompt-ready scope note, or null when there is nothing worth saying (root-scoped single-package repo). */
30: 	readonly note: string | null;
31: }
32: 
33: /** The deepest package dir that is a path prefix of `file` ("" always matches as the root). */
34: function packageDirForFile(file: string, packageDirs: readonly string[]): string {
35: 	let best = "";
36: 	for (const dir of packageDirs) {
37: 		if (dir !== "" && (file === dir || file.startsWith(`${dir}/`)) && dir.length > best.length) {
38: 			best = dir;
39: 		}
40: 	}
41: 	return best;
42: }
43: 
44: export function deriveMonorepoTaskScope(input: MonorepoTaskScopeInput): MonorepoTaskScope {
45: 	const files = [...new Set(input.taskFiles.map((file) => file.trim()).filter((file) => file.length > 0))];
46: 	const none: MonorepoTaskScope = { packageDir: null, spansPackages: null, instructionFilePaths: [], note: null };
47: 	if (files.length === 0 || input.packageDirs.length === 0) {
48: 		return none;
49: 	}
50: 	const resolved = [...new Set(files.map((file) => packageDirForFile(file, input.packageDirs)))].sort();
51: 	const instructionFilesFor = (packageDir: string): string[] => {
52: 		const governing = input.instructionFiles.filter((path) => {
53: 			const dir = path.includes("/") ? path.slice(0, path.lastIndexOf("/")) : "";
54: 			return dir === "" || packageDir === dir || packageDir.startsWith(`${dir}/`);
55: 		});
56: 		// Outermost first: nearest instructions render LAST, closest to the task text (recency wins).
57: 		return [...governing].sort((left, right) => left.length - right.length);
58: 	};
59: 
60: 	if (resolved.length > 1) {
61: 		const spanning = resolved.map((dir) => (dir === "" ? "(root)" : dir));
62: 		return {
63: 			packageDir: null,
64: 			spansPackages: resolved,
65: 			instructionFilePaths: [],
66: 			note: [
67: 				`[Monorepo scope] This card's files SPAN packages: ${spanning.join(", ")}.`,
68: 				"Cross-package changes are usually scope creep for one card — check whether the task really needs all of them; each package has its own scripts and checks.",
69: 			].join("\n"),
70: 		};
71: 	}
72: 	const packageDir = resolved[0] ?? "";
73: 	if (packageDir === "") {
74: 		// Root-scoped: the default context — nothing worth a note.
75: 		return none;
76: 	}
77: 	const instructionFilePaths = instructionFilesFor(packageDir);
78: 	return {
79: 		packageDir,
80: 		spansPackages: null,
81: 		instructionFilePaths,
82: 		note: [
83: 			`[Monorepo scope] Your working package is \`${packageDir}\` — its own package.json scripts govern builds/tests/lint there (root scripts may not cover it).`,
84: 			...(instructionFilePaths.length > 0
85: 				? [
86: 						`Instructions that govern this scope (outermost first): ${instructionFilePaths.join(", ")} — read the nearest one.`,
87: 					]
88: 				: []),
89: 		].join("\n"),
90: 	};
91: }
