41: export interface ExplorerRunnerDeps {
42: 	getAgentSandboxManager(): AgentSandboxManager | null;
43: 	getLaunchConfig(taskId: string): NKleinTaskRestartLaunchConfig | null;
44: 	resolveExplorerLaunchConfig(workerLaunch: NKleinTaskRestartLaunchConfig): Promise<NKleinTaskRestartLaunchConfig>;
45: 	getPauseController(): NKleinPauseController;
46: 	getHarness(): SecondarySessionHarness;
47: 	getBaseRef(taskId: string): string | null;
48: 	startRuntimeSession(input: StartRuntimeTaskSessionFromLaunchConfigInput): Promise<RuntimeTaskSessionStartResult>;
49: 	sendTaskSessionInput(taskId: string, prompt: string, admissionParentTaskId: string): Promise<unknown>;
50: 	defaultTimeoutMs: number;
51: 	maxNudges: number;
52: 	/** Per-run explore-query budget (each query is one bounded read-only session on the task's endpoint). */
53: 	runBudget: number;
