165: export function loadedModelDescriptorFromLmsPsModel(model: LmsPsModel): LoadedModelDescriptor {
166: 	return {
167: 		runtimeId: model.identifier,
168: 		modelKey: model.modelKey || model.identifier,
169: 		isEmbedding: model.isEmbedding,
170: 		...(model.trainedForToolUse !== null ? { toolUse: model.trainedForToolUse } : {}),
171: 		...(model.contextLength !== null ? { maxContextLength: model.contextLength } : {}),
172: 		...(model.contextLength !== null ? { loadedContextLength: model.contextLength } : {}),
173: 	};
174: }
