22: export interface LoadedModelDescriptor {
23: 	/** The runtime identifier to INVOKE — LM Studio's per-instance alias (`loaded_instances[].id`). Candidate identity. */
24: 	runtimeId: string;
25: 	/** The real publisher model key (`key`) for capability/catalog/llmfit lookups; falls back to `runtimeId` if absent. */
26: 	modelKey: string;
27: 	/** `true` for an embedding model (`type === "embedding"`) — authoritative, replaces name-pattern guessing. */
28: 	isEmbedding: boolean;
29: 	/** LM Studio's `capabilities.trained_for_tool_use`, when reported (undefined ⇒ the card didn't say). */
30: 	toolUse?: boolean;
31: 	/** F2.7b: LM Studio's `capabilities.vision`, when reported — the chat image gate's catalog-side signal. */
32: 	vision?: boolean;
33: 	/** `true` when the card declares a `reasoning` capability (a reasoner); undefined when not declared. */
34: 	reasoning?: boolean;
35: 	/** The architecture family string (e.g. `qwen3_5`, `phi3`, `mistral3`) — a coarse lineage hint. */
36: 	architecture?: string;
37: 	/** The model's advertised max context length, when present. */
38: 	maxContextLength?: number;
39: 	/** Context length of this loaded runtime instance, when LM Studio reports its instance config. */
40: 	loadedContextLength?: number;
41: 	/** On-disk/resident model bytes reported by LM Studio, when present; useful for relative loaded-fleet cost. */
42: 	sizeBytes?: number;
43: }
