70: /**
71:  * Parse an `/api/v1/models` payload into one {@link LoadedModelDescriptor} per LOADED instance (a model with a
72:  * non-empty `loaded_instances`). Tolerant of shape: a missing `key` falls back to the runtime id; an unknown `type`
73:  * is treated as a non-embedding LLM. Models with no loaded instances (residency-only entries) are skipped.
74:  */
75: export function parseLoadedModelDescriptors(payload: unknown): LoadedModelDescriptor[] {
76: 	// The NATIVE `/api/v1/models` wraps the list in `models`; the enhanced `/api/v0/models` uses `data`. Accept either
77: 	// (and a bare array) so the parser tracks reality, not one assumed envelope.
78: 	const container = payload && typeof payload === "object" ? (payload as { models?: unknown; data?: unknown }) : null;
79: 	const data = Array.isArray(payload)
80: 		? payload
81: 		: Array.isArray(container?.models)
82: 			? container.models
83: 			: Array.isArray(container?.data)
84: 				? container.data
85: 				: [];
86: 	const descriptors: LoadedModelDescriptor[] = [];
87: 	for (const entry of data) {
88: 		if (!entry || typeof entry !== "object") {
89: 			continue;
90: 		}
91: 		const model = entry as RawV1Model;
92: 		const sizeBytes =
93: 			typeof model.size_bytes === "number" && Number.isFinite(model.size_bytes) && model.size_bytes > 0
94: 				? model.size_bytes
95: 				: undefined;
96: 		const instances = Array.isArray(model.loaded_instances) ? model.loaded_instances : [];
97: 		if (instances.length === 0) {
98: 			const runtimeId = asString(model.id);
99: 			if (model.state === "loaded" && runtimeId) {
100: 				const caps = (model.capabilities ?? undefined) as RawV1Capabilities | undefined;

100: 				const caps = (model.capabilities ?? undefined) as RawV1Capabilities | undefined;
101: 				const toolUse = typeof caps?.trained_for_tool_use === "boolean" ? caps.trained_for_tool_use : undefined;
102: 				const vision = typeof caps?.vision === "boolean" ? caps.vision : undefined;
103: 				const reasoning = caps && caps.reasoning != null ? true : undefined;
104: 				const architecture = asString(model.architecture);
105: 				const maxContextLength =
106: 					typeof model.max_context_length === "number" && Number.isFinite(model.max_context_length)
107: 						? model.max_context_length
108: 						: undefined;
109: 				descriptors.push({
110: 					runtimeId,
111: 					modelKey: asString(model.key) ?? runtimeId,
112: 					isEmbedding: model.type === "embedding",
113: 					...(toolUse !== undefined ? { toolUse } : {}),
114: 					...(vision !== undefined ? { vision } : {}),
115: 					...(reasoning !== undefined ? { reasoning } : {}),
116: 					...(architecture !== undefined ? { architecture } : {}),
117: 					...(maxContextLength !== undefined ? { maxContextLength } : {}),
118: 					...(sizeBytes !== undefined ? { sizeBytes } : {}),
119: 				});
120: 			}
121: 			continue; // not loaded — skip (residency-only entry)
122: 		}
123: 		const modelKey = asString(model.key);
124: 		const isEmbedding = model.type === "embedding";
125: 		const caps = (model.capabilities ?? undefined) as RawV1Capabilities | undefined;
126: 		const toolUse = typeof caps?.trained_for_tool_use === "boolean" ? caps.trained_for_tool_use : undefined;
127: 		const vision = typeof caps?.vision === "boolean" ? caps.vision : undefined;
128: 		const reasoning = caps && caps.reasoning != null ? true : undefined;
129: 		const architecture = asString(model.architecture);
130: 		const maxContextLength =
131: 			typeof model.max_context_length === "number" && Number.isFinite(model.max_context_length)
132: 				? model.max_context_length
133: 				: undefined;
134: 		for (const rawInstance of instances) {
135: 			const instance = rawInstance as RawV1Instance;
136: 			const runtimeId = asString(instance?.id);
137: 			if (!runtimeId) {
138: 				continue;
139: 			}
140: 			const config =
141: 				instance.config && typeof instance.config === "object"
142: 					? (instance.config as { context_length?: unknown })
143: 					: null;
144: 			const loadedContextLength =
145: 				typeof config?.context_length === "number" && Number.isFinite(config.context_length)
146: 					? config.context_length
147: 					: undefined;
148: 			descriptors.push({
149: 				runtimeId,
150: 				modelKey: modelKey ?? runtimeId,
151: 				isEmbedding,
152: 				...(toolUse !== undefined ? { toolUse } : {}),
153: 				...(vision !== undefined ? { vision } : {}),
154: 				...(reasoning !== undefined ? { reasoning } : {}),
155: 				...(architecture !== undefined ? { architecture } : {}),
156: 				...(maxContextLength !== undefined ? { maxContextLength } : {}),
157: 				...(loadedContextLength !== undefined ? { loadedContextLength } : {}),
158: 				...(sizeBytes !== undefined ? { sizeBytes } : {}),
159: 			});
160: 		}
161: 	}
162: 	return descriptors;
163: }
