176: export function mergeLoadedModelDescriptors(
177: 	descriptors: readonly LoadedModelDescriptor[],
178: 	lmsPsModels: readonly LmsPsModel[],
179: ): LoadedModelDescriptor[] {
180: 	const byRuntimeId = new Map<string, LoadedModelDescriptor>();
181: 	for (const descriptor of descriptors) {
182: 		byRuntimeId.set(descriptor.runtimeId, descriptor);
183: 	}
184: 	for (const model of lmsPsModels) {
185: 		const runtimeId = model.identifier.trim();
186: 		if (!runtimeId || byRuntimeId.has(runtimeId)) {
187: 			continue;
188: 		}
189: 		byRuntimeId.set(runtimeId, loadedModelDescriptorFromLmsPsModel(model));
190: 	}
191: 	return [...byRuntimeId.values()];
192: }
