194: /** Map an OpenAI-style base URL (`http://host:port/v1`) to LM Studio's native `/api/v1/models` URL. */
195: export function lmStudioApiV1ModelsUrl(baseUrl: string): string {
196: 	const root = baseUrl.trim().replace(/\/+$/u, "").replace(/\/v1$/u, "");
197: 	return `${root}/api/v1/models`;
198: }
