62: export async function listSourceFiles(rootPath: string, maxFiles: number): Promise<string[]> {
63: 	const results: string[] = [];
64: 	async function visit(directoryPath: string): Promise<void> {
65: 		if (results.length >= maxFiles) {
66: 			return;
67: 		}
68: 		const entries = await readdir(directoryPath, { withFileTypes: true });
69: 		for (const entry of entries) {
70: 			if (results.length >= maxFiles) {
71: 				return;
72: 			}
73: 			const entryPath = join(directoryPath, entry.name);
74: 			if (entry.isDirectory()) {
75: 				if (!SKIPPED_DIRS.has(entry.name)) {
76: 					await visit(entryPath);
