10: export interface MonorepoScanFacts {
11: 	/** Directories containing a package.json, workspace-relative ("" = root). */
12: 	readonly packageDirs: readonly string[];
13: 	/** All AGENTS.md / CLAUDE.md paths, workspace-relative. */
14: 	readonly instructionFiles: readonly string[];
