23: async function walk(
24: 	root: string,
25: 	relativeDir: string,
26: 	depth: number,
27: 	packageDirs: string[],
28: 	instructionFiles: string[],
29: ): Promise<void> {
30: 	const entries = await readdir(join(root, relativeDir), { withFileTypes: true }).catch(() => []);
31: 	const subDirs: string[] = [];
32: 	for (const entry of entries) {
33: 		const relativePath = relativeDir ? `${relativeDir}/${entry.name}` : entry.name;
34: 		if (entry.isFile()) {
35: 			if (entry.name === "package.json") {
36: 				packageDirs.push(relativeDir);
37: 			} else if (INSTRUCTION_FILE_NAMES.has(entry.name)) {
38: 				instructionFiles.push(relativePath);
39: 			}
40: 		} else if (entry.isDirectory() && !entry.name.startsWith(".") && !SKIPPED_DIRS.has(entry.name)) {
41: 			subDirs.push(relativePath);
42: 		}
43: 	}
44: 	if (depth < SCAN_MAX_DEPTH) {
45: 		for (const subDir of subDirs) {
46: 			await walk(root, subDir, depth + 1, packageDirs, instructionFiles);
47: 		}
48: 	}
49: }
