28: const TS_EXTENSIONS = /\.(ts|tsx|js|jsx|mts|cts|mjs|cjs)$/i;
29: const MAX_EXEMPLAR_LINES = 50;
30: const MIN_OVERLAP_SCORE = 0.12;
31: const DEFAULT_MAX_FILES = 1_000;
