56: /** Extract every named, exemplar-sized function from a TS/JS file (declarations + arrow/function consts). */
57: export function extractFunctionExemplarCandidates(path: string, content: string): ExemplarCandidate[] {
58: 	if (!TS_EXTENSIONS.test(path)) {
59: 		return [];
60: 	}
61: 	let sourceFile: ts.SourceFile;
62: 	try {
63: 		sourceFile = ts.createSourceFile(
64: 			path,
65: 			content,
66: 			ts.ScriptTarget.Latest,
67: 			true,
68: 			/\.(tsx|jsx)$/i.test(path) ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
69: 		);
70: 	} catch {
71: 		return [];
72: 	}
73: 	const lines = content.split("\n");
74: 	const candidates: ExemplarCandidate[] = [];
75: 	const pushCandidate = (name: string, node: ts.Node): void => {
76: 		const lineStart = sourceFile.getLineAndCharacterOfPosition(node.getStart(sourceFile)).line + 1;
77: 		const lineEnd = sourceFile.getLineAndCharacterOfPosition(node.getEnd()).line + 1;
78: 		if (lineEnd - lineStart + 1 > MAX_EXEMPLAR_LINES) {
79: 			return;
80: 		}
81: 		const snippet = lines.slice(lineStart - 1, lineEnd).join("\n");
82: 		// Score on identity, not the whole body. Body tokens made generic helpers win because incidental words such as
83: 		// "task", "model", "file", or "result" appeared somewhere in almost every implementation. The rendered snippet
84: 		// remains complete; only retrieval relevance uses the stable name/path vocabulary.
85: 		candidates.push({ path, name, lineStart, lineEnd, snippet, tokens: tokenizeForOverlap(`${name} ${path}`) });
86: 	};
87: 	for (const statement of sourceFile.statements) {
88: 		if (ts.isFunctionDeclaration(statement) && statement.name && statement.body) {
89: 			pushCandidate(statement.name.text, statement);
90: 		} else if (ts.isVariableStatement(statement)) {
91: 			const declaration = statement.declarationList.declarations[0];
92: 			if (
93: 				declaration &&
94: 				ts.isIdentifier(declaration.name) &&
95: 				declaration.initializer &&
96: 				(ts.isArrowFunction(declaration.initializer) || ts.isFunctionExpression(declaration.initializer))
97: 			) {
98: 				pushCandidate(declaration.name.text, statement);
99: 			}
100: 		}
101: 	}
102: 	return candidates;
103: }
