105: /** Binary cosine overlap: stable when a precise task contract contains much more prose than a function identity. */
106: function overlapScore(taskTokens: ReadonlySet<string>, candidateTokens: ReadonlySet<string>): number {
107: 	if (taskTokens.size === 0 || candidateTokens.size === 0) {
108: 		return 0;
109: 	}
110: 	let hits = 0;
111: 	for (const token of taskTokens) {
112: 		if (candidateTokens.has(token)) {
113: 			hits += 1;
114: 		}
115: 	}
116: 	return hits / Math.sqrt(taskTokens.size * candidateTokens.size);
117: }
