120: export function selectFewShotExemplars(options: {
121: 	taskText: string;
122: 	/** The card's own target files — excluded (the worker reads those anyway; an exemplar must be OTHER code). */
123: 	targetPaths: readonly string[];
124: 	candidates: readonly ExemplarCandidate[];
125: 	maxExemplars?: number;
126: }): FewShotExemplar[] {
127: 	const taskTokens = tokenizeForOverlap(options.taskText);
128: 	const targetPathSet = new Set(options.targetPaths);
129: 	const maxExemplars = Math.max(1, Math.min(4, options.maxExemplars ?? 2));
130: 	const scored = options.candidates
131: 		.filter((candidate) => !targetPathSet.has(candidate.path))
132: 		.map((candidate) => ({ candidate, score: overlapScore(taskTokens, candidate.tokens) }))
133: 		.filter((entry) => entry.score >= MIN_OVERLAP_SCORE)
134: 		.sort(
135: 			(left, right) =>
136: 				right.score - left.score ||
137: 				`${left.candidate.path}:${left.candidate.name}`.localeCompare(
138: 					`${right.candidate.path}:${right.candidate.name}`,
139: 				),
140: 		);
141: 	const picked: FewShotExemplar[] = [];
142: 	const usedPaths = new Set<string>();
143: 	for (const entry of scored) {
144: 		if (picked.length >= maxExemplars) {
145: 			break;
146: 		}
147: 		// One exemplar per file — two shots from the same file teach less than two files' worth of house style.
148: 		if (usedPaths.has(entry.candidate.path)) {
149: 			continue;
150: 		}
151: 		usedPaths.add(entry.candidate.path);
152: 		const { tokens: _tokens, ...exemplar } = entry.candidate;
153: 		picked.push({ ...exemplar, score: entry.score });
154: 	}
155: 	return picked;
156: }
