47: interface ExemplarCandidate {
48: 	readonly path: string;
49: 	readonly name: string;
50: 	readonly lineStart: number;
51: 	readonly lineEnd: number;
52: 	readonly snippet: string;
53: 	readonly tokens: Set<string>;
