164: 		"[Style exemplars: similar EXISTING functions from this repo. Match their conventions (naming, error handling, docs) — do not copy their logic.]",
165: 		...exemplars.map((exemplar) =>
166: 			[`— ${exemplar.path}:${exemplar.lineStart} (${exemplar.name})`, "```", exemplar.snippet, "```"].join("\n"),
167: 		),
168: 	].join("\n");
169: }
