1: /**
2:  * F11.2k workspace scan for monorepo task scoping: find every package.json directory and every
3:  * AGENTS.md/CLAUDE.md in the workspace (bounded depth, node_modules/.git/dist skipped), memoized per workspace —
4:  * one walk serves every card start. The derivation over these facts is the pure core (`monorepo-task-scope`).
5:  */
6: 
7: import { readdir } from "node:fs/promises";
8: import { join } from "node:path";
9: 
10: export interface MonorepoScanFacts {
11: 	/** Directories containing a package.json, workspace-relative ("" = root). */
12: 	readonly packageDirs: readonly string[];
13: 	/** All AGENTS.md / CLAUDE.md paths, workspace-relative. */
14: 	readonly instructionFiles: readonly string[];
15: }
16: 
17: const SCAN_MAX_DEPTH = 4;
18: const SKIPPED_DIRS = new Set(["node_modules", "dist", "build", "coverage", ".git", ".nklein"]);
19: const INSTRUCTION_FILE_NAMES = new Set(["AGENTS.md", "CLAUDE.md"]);
20: 
21: const factsByWorkspace = new Map<string, MonorepoScanFacts>();
22: 
23: async function walk(
24: 	root: string,
25: 	relativeDir: string,
26: 	depth: number,
27: 	packageDirs: string[],
28: 	instructionFiles: string[],
29: ): Promise<void> {
30: 	const entries = await readdir(join(root, relativeDir), { withFileTypes: true }).catch(() => []);
31: 	const subDirs: string[] = [];
32: 	for (const entry of entries) {
33: 		const relativePath = relativeDir ? `${relativeDir}/${entry.name}` : entry.name;
34: 		if (entry.isFile()) {
35: 			if (entry.name === "package.json") {
36: 				packageDirs.push(relativeDir);
37: 			} else if (INSTRUCTION_FILE_NAMES.has(entry.name)) {
38: 				instructionFiles.push(relativePath);
39: 			}
40: 		} else if (entry.isDirectory() && !entry.name.startsWith(".") && !SKIPPED_DIRS.has(entry.name)) {
41: 			subDirs.push(relativePath);
42: 		}
43: 	}
44: 	if (depth < SCAN_MAX_DEPTH) {
45: 		for (const subDir of subDirs) {
46: 			await walk(root, subDir, depth + 1, packageDirs, instructionFiles);
47: 		}
48: 	}
49: }
50: 
51: /** Scan (memoized per workspace). Best-effort: unreadable trees yield empty facts, never an error. */
52: export async function scanMonorepoFacts(workspacePath: string): Promise<MonorepoScanFacts> {
53: 	const cached = factsByWorkspace.get(workspacePath);
54: 	if (cached) {
55: 		return cached;
56: 	}
57: 	const packageDirs: string[] = [];
58: 	const instructionFiles: string[] = [];
59: 	await walk(workspacePath, "", 0, packageDirs, instructionFiles).catch(() => undefined);
60: 	const facts: MonorepoScanFacts = { packageDirs, instructionFiles };
61: 	factsByWorkspace.set(workspacePath, facts);
62: 	return facts;
63: }
64: 
65: /** Test/maintenance hook: clear the per-workspace memo. */
66: export function clearMonorepoScanMemo(): void {
67: 	factsByWorkspace.clear();
68: }
