1: /**
2:  * End-of-context task re-anchor for long runs (todo §5.AD / §5.N — context management).
3:  *
4:  * Research background (§5.AD): LLMs degrade on long contexts via two distinct failure modes:
5:  *   1. **Lost-in-the-middle** (Liu et al. 2023) — attention is U-shaped; mid-context content is attended to worst.
6:  *   2. **Goal dilution** — after many tool calls, retrieval results, and partial progress updates the model can lose
7:  *      the top-level task and start optimising for the wrong sub-goal. This is distinct from the positional problem
8:  *      and is especially acute for weak/small models running long agentic chains (see §5.N "task drift").
9:  *
10:  * This module provides the **pure policy layer** for a `beforeModel` hook that re-injects a compact re-anchor block
11:  * near the END of the assembled context (the strong end-zone, see `context-smart-zone.ts`), periodically, so the
12:  * model is reminded of the original task right before it generates its next action.
13:  *
14:  * Two responsibilities, cleanly separated:
15:  *  1. **When** to re-anchor — {@link shouldReanchor} is a pure cadence gate driven by turn counters.
16:  *  2. **What** to inject — {@link buildContextReanchor} formats the compact re-anchor block from structured input.
17:  *
18:  * Pure + stateless (no I/O, no side-effects), so both functions are unit-testable in isolation.
19:  */
20: 
21: /** Input for building a re-anchor block. All optional fields are silently skipped when absent or blank. */
22: export interface ContextReanchorInput {
23: 	/** The top-level task / goal the agent was given. Required; if blank the block is still emitted as a reminder. */
24: 	goal: string;
25: 	/** The current step or sub-task the agent is working on, if known. */
26: 	currentStep?: string | null;
27: 	/** The Kanban card title, if the context is card-scoped. */
28: 	cardTitle?: string | null;
29: 	/**
30: 	 * The most-recent N tool names the agent has called (ordered oldest→newest). Included when given to help the
31: 	 * model situate itself in the action stream and avoid repeating work.
32: 	 */
33: 	recentToolNames?: readonly string[];
34: 	/**
35: 	 * F4.8: the card's hard CONSTRAINTS — what the agent must not do. Re-anchoring the goal without them lets a
36: 	 * long run drift into a solution that satisfies the objective by violating a boundary, which reads as success
37: 	 * until someone looks.
38: 	 */
39: 	constraints?: string | null;
40: 	/**
41: 	 * F4.8: the ACCEPTANCE CRITERIA — what "done" means. This is the element long runs lose most damagingly: an
42: 	 * agent that has forgotten the definition of done will confidently declare it.
43: 	 */
44: 	acceptanceCriteria?: string | null;
45: }
46: 
47: /**
48:  * Build a compact, clearly-delimited re-anchor block for injection near the end of a long context.
49:  *
50:  * Design constraints:
51:  *  - Kept intentionally short — it's appended/prepended to a request that may already be large.
52:  *  - XML-tag delimited so the model recognises it as a distinct framing block (Anthropic guidance for multi-section
53:  *    prompts; consistent with `renderSmartZoneContext({tagParts: true})`).
54:  *  - Empty or whitespace-only optional fields are silently omitted so callers can pass nullable values freely.
55:  */
56: export function buildContextReanchor(input: ContextReanchorInput): string {
57: 	const lines: string[] = [];
58: 
59: 	const goal = input.goal.trim();
60: 	lines.push(`GOAL: ${goal}`);
61: 
62: 	const cardTitle = input.cardTitle?.trim();
63: 	if (cardTitle) {
64: 		lines.push(`CARD: ${cardTitle}`);
65: 	}
66: 
67: 	const currentStep = input.currentStep?.trim();
68: 	if (currentStep) {
69: 		lines.push(`CURRENT STEP: ${currentStep}`);
70: 	}
71: 
72: 	// F4.8's two missing elements. Placed BEFORE recent tools so that, if anything is ever truncated, the boundary
73: 	// conditions survive and the action log is what gets lost — the reverse ordering would drop the constraints a
74: 	// long run is most likely to have forgotten.
75: 	const constraints = input.constraints?.trim();
76: 	if (constraints) {
77: 		lines.push(`CONSTRAINTS: ${constraints}`);
78: 	}
79: 
80: 	const acceptanceCriteria = input.acceptanceCriteria?.trim();
81: 	if (acceptanceCriteria) {
82: 		// Preserve the canonical contract vocabulary. Weak local models can treat a friendly synonym such as
83: 		// "DONE MEANS" as a different field and then recover an older literal "acceptance" value from context.
84: 		lines.push(`ACCEPTANCE CRITERIA: ${acceptanceCriteria}`);
85: 	}
86: 
87: 	const recentTools = input.recentToolNames?.filter((t) => t.trim().length > 0);
88: 	if (recentTools && recentTools.length > 0) {
89: 		lines.push(`RECENT TOOLS: ${recentTools.join(", ")}`);
90: 	}
91: 
92: 	const body = lines.join("\n");
93: 	return `<reanchor>\n${body}\n</reanchor>`;
94: }
