21: 	/** 1-based line when the citation is that precise; null for whole-file relevance. */
22: 	line: z.number().int().positive().nullable().optional().default(null),
23: 	/** One line: WHY this location matters for the question. */
24: 	note: z.string().min(1),
25: });
