43: export function createNKleinExplorerCitationsTool(options: {
44: 	onSubmitted?: NKleinExplorerCitationsSubmittedHandler;
45: }): AgentTool {
46: 	return {
47: 		name: "submit_citations",
48: 		description:
49: 			"Submit your exploration findings. Call this exactly once with a short `answer` and 1–12 `citations` ({path, line, note}) naming exactly WHERE the relevant code lives and why each location matters. Do not answer in prose; the findings are delivered by this tool call.",
50: 		inputSchema: {
51: 			type: "object",
52: 			properties: {
53: 				// Models sometimes echo the tool name inside the arguments — tolerated and ignored (Zod strips it).
54: 				name: { type: ["string", "null"], description: "Ignored. Do not include." },
55: 				answer: { type: "string", description: "A few sentences answering the question directly." },
56: 				citations: {
57: 					type: "array",
58: 					items: {
59: 						type: "object",
60: 						properties: {
61: 							path: { type: "string", description: "Workspace-relative file path." },
62: 							line: { type: ["number", "null"], description: "1-based line, or null for whole-file relevance." },
63: 							note: { type: "string", description: "One line: why this location matters." },
64: 						},
65: 						required: ["path", "note"],
66: 					},
67: 					description: "1–12 read targets, most relevant first.",
68: 				},
69: 			},
70: 			required: ["answer", "citations"],
71: 		},
72: 		async execute(input) {
73: 			const parsed = nkleinExplorerSubmissionSchema.safeParse(input);
74: 			if (!parsed.success) {
75: 				return {
76: 					error: "Could not read the findings. Call submit_citations with a non-empty `answer` and 1–12 `citations` of {path, line, note}.",
77: 				};
78: 			}
79: 			await options.onSubmitted?.({
80: 				answer: parsed.data.answer,
81: 				citations: parsed.data.citations.map((citation) => ({
82: 					path: citation.path,
83: 					line: citation.line ?? null,
84: 					note: citation.note,
85: 				})),
86: 			});
87: 			return { ok: true, message: "Findings recorded. You are done — do not continue exploring." };
88: 		},
89: 	};
90: }
