65: export function createExplorerRunner(deps: ExplorerRunnerDeps): ExplorerRunner {
66: 	async function runExplorerSession(input: {
67: 		taskId: string;
68: 		projectRepoPath: string;
69: 		baseRef: string;
70: 		question: string;
71: 	}): Promise<NKleinExplorerResult | null> {
72: 		const sandboxManager = deps.getAgentSandboxManager();
73: 		if (!sandboxManager) {
74: 			return null;
75: 		}
76: 		const workerLaunch = deps.getLaunchConfig(input.taskId) ?? null;
77: 		if (!workerLaunch?.providerId || !workerLaunch.modelId) {
78: 			return null;
79: 		}
80: 		const selectedLaunch = await deps.resolveExplorerLaunchConfig(workerLaunch).catch(() => workerLaunch);
81: 		const launchConfig: NKleinTaskRestartLaunchConfig = {
82: 			...selectedLaunch,
83: 			workspaceRoot: input.projectRepoPath,
84: 		};
85: 		if (launchConfig.modelId !== workerLaunch.modelId) {
86: 			recordSelfObservation({
87: 				signal: "custom",
88: 				severity: "info",
89: 				message: `Explorer for ${input.taskId} routed from ${workerLaunch.modelId} to smaller loaded model ${launchConfig.modelId}.`,
90: 				taskId: input.taskId,
91: 				metadata: {
92: 					category: "explorer_smaller_model_routed",
93: 					workerModel: workerLaunch.modelId,
94: 					explorerModel: launchConfig.modelId,
95: 				},
96: 			});
97: 		}
98: 		const explorerTaskId = `${input.taskId}::explore`;
99: 		return deps.getHarness().runBracketed(
100: 			{
101: 				syntheticTaskId: explorerTaskId,
102: 				projectRepoPath: input.projectRepoPath,
103: 				baseRef: input.baseRef,
104: 				defaultTimeoutMs: deps.defaultTimeoutMs,
105: 				errorLabel: "Explorer session",
106: 			},
107: 			async ({ workspace, deadlineMs, runBoundedTurn }) => {
108: 				let findings: NKleinExplorerResult | null = null;
109: 				await runBoundedTurn(
110: 					deps.startRuntimeSession({
111: 						taskId: explorerTaskId,
112: 						admissionParentTaskId: input.taskId,
113: 						cwd: workspace.workdir,
114: 						workspaceRoot: input.projectRepoPath,
115: 						prompt: buildExplorerSeedPrompt(input.question),
116: 						launchConfig,
117: 						contextScope: "minimal",
118: 						onExplorerCitationsSubmitted: (result) => {
119: 							findings = result;
120: 						},

120: 						},
121: 						toolExecutors: createAgentSandboxToolExecutors(sandboxManager, explorerTaskId, {
122: 							pauseController: deps.getPauseController(),
123: 						}),
124: 						extraTools: createAgentSandboxExtraTools(sandboxManager, explorerTaskId, {
125: 							sessionId: createSessionId(explorerTaskId),
126: 							contextWindow: launchConfig.contextWindow ?? undefined,
127: 							maxFileLines: launchConfig.maxAgentWritableFileLines ?? null,
128: 						}),
129: 					}),
130: 				);
131: 				for (let nudge = 0; findings === null && nudge < deps.maxNudges && Date.now() < deadlineMs; nudge += 1) {
132: 					await runBoundedTurn(deps.sendTaskSessionInput(explorerTaskId, EXPLORER_NUDGE_PROMPT, input.taskId));
133: 				}
134: 				return findings;
135: 			},
136: 		);
137: 	}
138: 
139: 	function buildExploreHandler(taskId: string, projectRepoPath: string): NKleinExplorerQueryHandler | undefined {
140: 		if (isDerivedTaskSessionId(taskId) || isHomeAgentSessionId(taskId)) {
141: 			return undefined;
142: 		}
143: 		// One closure belongs to one worker session. Keeping this counter on the runner made six historical calls disable
144: 		// exploration globally for every later task in the service lifetime.
145: 		let exploreQueriesUsed = 0;
146: 		return async (question) => {
147: 			if (exploreQueriesUsed >= deps.runBudget) {
148: 				return null;
149: 			}
150: 			if (!deps.getAgentSandboxManager()) {
151: 				return null;
152: 			}
153: 			exploreQueriesUsed += 1;
154: 			return await runExplorerSession({
155: 				taskId,
156: 				projectRepoPath,
157: 				baseRef: deps.getBaseRef(taskId) ?? "HEAD",
158: 				question,
159: 			}).catch((error: unknown) => {
160: 				// P21.7 follow-up: the return stays null (the tool renders an honest fallback — nothing to salvage
161: 				// from a read-only helper query), but the FAILURE was previously swallowed silently, so a timed-out
162: 				// explore looked identical to one that legitimately found nothing. Record the classified reason so
163: 				// "explore keeps timing out" is visible instead of invisible — the record-the-decline rule applied
164: 				// to a helper path.
165: 				const message = error instanceof Error ? error.message : String(error);
166: 				const reason = classifyExploreFailure(message);
167: 				try {
168: 					recordSelfObservation({
169: 						signal: "custom",
170: 						severity: "info",
171: 						message: `Explore query for ${taskId} failed: ${reason === "timeout" ? "timed out" : "errored"}.`,
172: 						taskId,
173: 						metadata: { category: "explore_query_failed", reason },
174: 					});
175: 				} catch {
176: 					// Telemetry must never break the explore fallback.
177: 				}
178: 				return null;
179: 			});
180: 		};
181: 	}
182: 
183: 	return { buildExploreHandler };
184: }
